import{_ as a,o as e,c as i,a4 as t}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"Flyme 官方 root 开启 ADB TCP 方案","description":"","frontmatter":{"title":"Flyme 官方 root 开启 ADB TCP 方案","date":"2026-07-03T00:00:00.000Z"},"headers":[],"relativePath":"posts/Flyme_ADB_TCP方案.md","filePath":"posts/Flyme_ADB_TCP方案.md"}'),n={name:"posts/Flyme_ADB_TCP方案.md"};function l(d,s,p,o,h,r){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="flyme-官方-root-开启-adb-tcp-方案" tabindex="-1">Flyme 官方 root 开启 ADB TCP 方案 <a class="header-anchor" href="#flyme-官方-root-开启-adb-tcp-方案" aria-label="Permalink to &quot;Flyme 官方 root 开启 ADB TCP 方案&quot;">​</a></h1><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Flyme 官方 root 的 <code>su</code> 运行在 <code>u:r:shell:s0</code> 上下文，无法直接控制 adbd：</p><ul><li><code>ctl.restart adbd</code> — 需要 init 上下文，shell 无权</li><li><code>stop/start adbd</code> — adbd 是 oneshot 服务，shell 拉不起来</li><li>直接写 <code>/dev/socket/adbd</code> — 内部传输接口，不接受用户命令</li><li>ADB 协议帧 — 连接即断（EOF）</li></ul><h2 id="解决方案-sys-usb-config-切换法" tabindex="-1">解决方案：sys.usb.config 切换法 <a class="header-anchor" href="#解决方案-sys-usb-config-切换法" aria-label="Permalink to &quot;解决方案：sys.usb.config 切换法&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>APP → su → 脚本</span></span>
<span class="line"><span>  ├── setprop service.adb.tcp.port 5555</span></span>
<span class="line"><span>  ├── setprop sys.usb.config none    ← init 监听到变化</span></span>
<span class="line"><span>  ├── sleep 1</span></span>
<span class="line"><span>  └── setprop sys.usb.config adb     ← init 再次监听到</span></span>
<span class="line"><span>                                        ↓</span></span>
<span class="line"><span>                                  init 执行 on property 触发器</span></span>
<span class="line"><span>                                  ├── stop adbd</span></span>
<span class="line"><span>                                  └── start adbd  ← init 有权限！</span></span>
<span class="line"><span>                                        ↓</span></span>
<span class="line"><span>                                  新 adbd 读到端口</span></span>
<span class="line"><span>                                  → TCP 5555 开放 ✓</span></span></code></pre></div><h3 id="关键原理" tabindex="-1">关键原理 <a class="header-anchor" href="#关键原理" aria-label="Permalink to &quot;关键原理&quot;">​</a></h3><p><code>sys.usb.config</code> 是 Android 系统属性，init 进程会监听它的变化。当值变为 <code>adb</code> 时，init.rc 中定义的触发器被执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>on property:sys.usb.config=adb &amp;&amp; property:sys.usb.configfs=0</span></span>
<span class="line"><span>    start adbd</span></span></code></pre></div><p>因为 <strong>init 自己执行 <code>start adbd</code></strong>，不受 SELinux 上下文限制，adbd 正常启动并读取 <code>service.adb.tcp.port</code> 属性。</p><h3 id="对比直接-ctl-restart" tabindex="-1">对比直接 <code>ctl.restart</code> <a class="header-anchor" href="#对比直接-ctl-restart" aria-label="Permalink to &quot;对比直接 \`ctl.restart\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th style="text-align:center;">执行者</th><th style="text-align:center;">SELinux 上下文</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td><code>setprop ctl.restart adbd</code></td><td style="text-align:center;">shell</td><td style="text-align:center;">u:r🐚s0</td><td style="text-align:center;">拒绝</td></tr><tr><td><code>sys.usb.config=adb</code> 触发器</td><td style="text-align:center;">init</td><td style="text-align:center;">u:r:init:s0</td><td style="text-align:center;">允许 ✓</td></tr></tbody></table><h2 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h2><h3 id="脚本-data-local-flyme-adb-sh" tabindex="-1">脚本 <code>/data/local/flyme_adb.sh</code> <a class="header-anchor" href="#脚本-data-local-flyme-adb-sh" aria-label="Permalink to &quot;脚本 \`/data/local/flyme_adb.sh\`&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">#!/system/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setprop</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> service.adb.tcp.port</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 5555</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setprop</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> sys.usb.config</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> none</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">sleep</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 1</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setprop</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> sys.usb.config</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> adb</span></span></code></pre></div><h3 id="开机自启-app" tabindex="-1">开机自启 APP <a class="header-anchor" href="#开机自启-app" aria-label="Permalink to &quot;开机自启 APP&quot;">​</a></h3><p>编译 ADB Boot Helper APK（BootReceiver + 前台服务），安装后打开一次授权 su：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>打开 APP → 授权 su → ADB TCP 即刻开启 ✓</span></span>
<span class="line"><span>重启后：BootReceiver → 前台服务 → 15秒后执行脚本 → TCP 自启 ✓</span></span></code></pre></div><h3 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">adb</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> connect</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &lt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">设备I</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">P</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">&gt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">:5555</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">adb</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> devices</span></span></code></pre></div><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>切换 <code>sys.usb.config</code> 会短暂断开 USB 连接（系统播放断开声），属于正常现象</li><li>Flyme 官方 root 的授权记忆可能不覆盖后台 BroadcastReceiver，依赖前台服务保持生命周期</li></ul>`,22)])])}const b=a(n,[["render",l]]);export{k as __pageData,b as default};
